"""Build an accessible, dependency-free Traditional Chinese benchmark site."""
from pathlib import Path
import json,html,math,zipfile,hashlib
ROOT=Path(__file__).resolve().parents[1]
A=json.loads((ROOT/'data/analysis.json').read_text(encoding='utf-8'))
M=json.loads((ROOT/'data/models.json').read_text(encoding='utf-8'))
S=json.loads((ROOT/'data/sources.json').read_text(encoding='utf-8'))
REPO='https://github.com/gregorytsai/zh-en-retrieval-benchmark'
SITE='https://gregorytsai.github.io/zh-en-retrieval-benchmark/'
DIRS={'eng-zho':'中文查英文','zho-zho':'中文查中文','eng-eng':'英文查英文'}
E=['granite-97m-r2','embeddinggemma-2','bge-m3','f2llm-v2-0.6b','qwen-0.6b','qwen-4b','qwen-8b']
R=['bge-reranker','qwen-reranker-0.6b','qwen-reranker-4b']
def esc(x):return html.escape(str(x))
def pct(x):return f'{x*100:.2f}%'
def ms(x):return f'{x:.2f} ms' if x<100 else f'{x/1000:.2f} 秒'
def name(k):return '不重排' if k=='standalone' else M[k]['short_name']
def link(k,pre=''):return f'<a href="{pre}models/{k}.html">{esc(name(k))}</a>'
def pair(e,r='standalone'):return next(x for x in A['pairs'] if x['embedding']==e and x['reranker']==r)
def group(e,r,c):return next(x for x in A['directions'] if (x['embedding'],x['reranker'],x['config'])==(e,r,c))
def table(headers,rows,cls=''):
 return f'<div class="table-scroll {cls}" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def page(path,title,body,desc='',pre=''):
 out=f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(desc or title)}"><meta name="theme-color" content="#112e3d"><title>{esc(title)}｜中英檢索實驗室</title><link rel="canonical" href="{SITE+path}"><link rel="icon" href="{pre}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{pre}assets/style.css"><script src="{pre}assets/app.js" defer></script></head><body><a class="skip" href="#main">跳至主要內容</a><header><a class="brand" href="{pre}index.html"><span class="brandmark">↗</span> 中英檢索實驗室<span class="brand-sub">LOCAL RETRIEVAL / 2026</span></a><nav aria-label="主要導覽"><a href="{pre}index.html#results">測試結果</a><a href="{pre}index.html#choose">選擇組合</a><a href="{pre}models.html">全部模型</a><a href="{pre}methods.html">完整說明</a><a href="{pre}resources.html">資料與程式</a></nav></header><main id="main">{body}</main><footer><div><strong>中英檢索實驗室</strong><p>實測完成：2026-10-22 22:23（臺灣時間） · guarded v3</p><p>本機研究結果；不代表各種硬體、知識庫或最終回答品質。</p></div><div><a href="{REPO}">GitHub 專案 ↗</a> · <a href="{pre}resources.html#license">授權與來源</a><p>MLQA 素材：CC BY-SA 3.0<br>自有程式碼：MIT</p></div></footer></body></html>'''
 out=out.replace('</div></footer>','<p>聯絡：<a href="mailto:gregorytsai@gmail.com">gregorytsai@gmail.com</a></p></div></footer>')
 if path=='index.html':
  out=out.replace('</head>','<link rel="stylesheet" href="assets/interactions.css"></head>')
  out=out.replace('</head>','<meta name="google-site-verification" content="mWQ59Rie_MkAK8-ilMG1MrZ9TO_OLtLBGmgvyCpdYcQ" /></head>')
 (ROOT/path).write_text(out,encoding='utf-8')
def intro(k,title,text):return f'<section class="page-intro"><p class="eyebrow">{k}</p><h1>{title}</h1><p class="lead">{text}</p></section>'
def sectionhead(k,title,text=''):return f'<div class="section-head"><div><p class="eyebrow">{k}</p><h2>{title}</h2></div><p>{text}</p></div>'
def bars():
 rows=[]
 for e in sorted(E,key=lambda k:pair(k)['top1'],reverse=True):
  p=pair(e);rows.append(f'<div class="metric-row"><a href="models/{e}.html">{esc(name(e))}</a><div class="metric-track"><span class="metric-base" style="width:{p["top1"]*100}%"></span></div><div class="metric-value"><strong>{pct(p["top1"])}</strong><small>{ms(p["total_ms_mean"])} · 單模型</small></div></div>')
 controls='<div class="chart-controls">'
 for key,label,options in [('direction','檢索方向',[('all','全部平均'),*DIRS.items()]),('reranker','重排器',[('standalone','不加重排器'),*[(r,name(r)) for r in R]])]:
  controls+=f'<fieldset id="chart-{key}"><legend>{label}</legend><div class="chart-buttons">'+''.join(f'<button type="button" data-value="{value}" aria-pressed="{str(i==0).lower()}" aria-controls="retrieval-bars">{esc(text)}</button>' for i,(value,text) in enumerate(options))+'</div></fieldset>'
 controls+='</div>'
 return controls+'<p id="chart-summary" class="small" aria-live="polite">全部平均 · 不加重排器；按命中率由高到低排列。</p><div class="chart-legend"><span><i class="legend-base"></i>單用 embedder</span><span><i class="legend-gain"></i>重排後增加</span><span><i class="legend-loss"></i>重排後減少（若有）</span></div><div class="metric-axis" aria-hidden="true"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div><div id="retrieval-bars">'+''.join(rows)+'</div><p class="small">長條固定從 0% 到 100%；增加幅度以「百分點」計算，例如 72% → 95% 是 +23 百分點。右側時間為該方向／組合的平均總時間。重排後依最終命中率排序；未測配對列於底部。</p>'
def comparison_table():
 headers=['Embedder','Reranker','中文查英文','中文查中文','英文查英文','平均 Top-1','平均總時間','總時間 p95','權重 GiB']
 head=''.join(f'<th scope="col" aria-sort="{"descending" if i==5 else "none"}"><button type="button" class="sort-button" data-column="{i}" data-label="{h}">{h}<span aria-hidden="true">{" ↓" if i==5 else " ↕"}</span></button></th>' for i,h in enumerate(headers))
 rows=[]
 for p,cells in zip(A['pairs'],matrix_rows()):
  values=[name(p['embedding']),name(p['reranker']),*[group(p['embedding'],p['reranker'],c)['top1'] for c in DIRS],p['top1'],p['total_ms_mean'],p['total_ms_p95'],p['weight_gib_sum']]
  rows.append(f'<tr data-sort-values="{esc(json.dumps(values,ensure_ascii=False))}">'+''.join('<td>'+str(c)+'</td>' for c in cells)+'</tr>')
 return '<div class="table-scroll" tabindex="0"><table aria-label="22 種組合完整比較"><thead><tr>'+head+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'
def matrix_rows():
 return [[link(p['embedding']),link(p['reranker']) if p['reranker']!='standalone' else '<span class="muted">不重排</span>',*[pct(group(p['embedding'],p['reranker'],c)['top1']) for c in DIRS],f'<strong>{pct(p["top1"])}</strong>',ms(p['total_ms_mean']),ms(p['total_ms_p95']),f'{p["weight_gib_sum"]:.3f}'] for p in A['pairs']]
def recommendation(e,r,label,text):
 p=pair(e,r)
 return f'<article class="recommend"><p class="eyebrow">{label}</p><h3>{link(e)}'+(f'<span class="plus">＋</span>{link(r)}' if r!='standalone' else '')+f'</h3><div class="rec-number">{pct(p["top1"])}<small>第一名命中率</small></div><p>{text}</p><div class="mini-stats"><span>{p["weight_gib_sum"]:.3f} GiB<small>權重合計</small></span><span>{ms(p["total_ms_mean"])}<small>本機平均時間</small></span></div></article>'

hero='''<section class="hero"><div><p class="eyebrow">7 EMBEDDERS · 3 RERANKERS · 中英實測</p><h1>中文問題，<br>找到對的英文資料。</h1><p class="lead">模型不必一律選最大。這份實測把「找得準、等多久、模型多大」放在一起，幫你挑適合的搜尋組合。</p><div class="hero-actions"><a class="button" href="#choose">先看怎麼選 ↓</a><a class="button secondary" href="#results">比較全部結果</a></div><p class="small">這是檢索與重排測試，沒有生成翻譯；「命中」指找到標註的相關文章。</p></div><div class="hero-visual" role="img" aria-label="中文問題先經 embedder 找出50篇候選，再由 reranker 重排，選出最相關文章"><div class="query-bubble"><span>你的問題 / 中文</span>以中文輸入搜尋問題</div><div class="flow-line">↓</div><div class="flow-stage"><b>01</b><div><strong>Embedder 找候選</strong><span>把問題與文章轉成向量，先找相近的 50 篇。</span></div><span class="document-stack">▤</span></div><div class="flow-line">↓ <small>可選擇加上這一步</small></div><div class="flow-stage accent"><b>02</b><div><strong>Reranker 再排序</strong><span>一起讀問題與候選文章，把相關資料往前排。</span></div><span class="document-stack">≋</span></div><div class="answer-bubble"><span>找到的原文 / 英文</span>與問題最相關的英文文章<small>流程示意 · 搜尋文章，不是生成翻譯</small></div></div></section>
<div class="evidence-strip"><div><strong>93.67<span>%</span></strong><span>本輪最高組合 Top-1</span></div><div><strong>22<span> 種</span></strong><span>模型組合 × 3 個方向</span></div><div><strong>300<span> 題</span></strong><span>不同方向／問題任務</span></div><div><strong>6,600<span> 筆</span></strong><span>正式測量，逐筆核對通過</span></div></div>
<p class="context-line">同一套條件：Apple M3 Ultra · 256 GiB 統一記憶體 · Metal GPU · Q8_0 · 每方向 100 題 · 重排 50 篇</p>'''
findings='''<section id="findings">'''+sectionhead('01 / 先看重點','把額外算力，花在有幫助的地方。','以下是本次資料的觀察，不是所有知識庫的通則。')+'''<div class="findings"><article class="finding primary"><span class="ordinal">01</span><h3>加大重排器後，<br>五種 embedder 的 Top-1 打平。</h3><div class="big">281 / 300</div><p>五款主要 embedder 搭配 Qwen 4B reranker，都找到 281 題的相關文章，平均 93.67%。小型組合值得優先評估，不必直接升到 8B。</p><p class="small">總分相同，不代表每題或完整排序相同；MRR 與 nDCG 仍有差異。</p></article><article class="finding"><span class="ordinal">02</span><h3>大重排器的收益，<br>主要出現在中文查英文。</h3><div class="direction-gain"><div><span>中文查英文</span><b>+10.2 <small>百分點</small></b></div><div><span>英文查英文</span><b>+0.4 <small>百分點</small></b></div></div><p>Qwen reranker 從 0.6B 升至 4B 的方向平均增益；重排平均時間卻從 1.16 秒增加至 6.29 秒。</p><a href="methods.html#findings">與官方已知內容對照 ↗</a></article></div></section>'''
choose='<section id="choose">'+sectionhead('02 / 依資源與等待時間選擇','先決定，你願意等多久。','卡片列出已測組合；容量是 Q8_0 權重檔案總和，不能直接當成 RAM／VRAM 最低需求。')+'<div class="recommend-grid">'
choose+=recommendation('bge-m3','standalone','輕量／優先快速回應','本次小型模型中兼顧速度與品質。F2LLM 為 78.00%，只比它多命中 1 題，先用自己的資料比較。')
choose+=recommendation('qwen-0.6b','bge-reranker','輕量組合／約一秒等待','想比單用 embedder 更準，且偏重反應速度，可從這組開始。單次重排 50 篇。')
choose+=recommendation('qwen-0.6b','qwen-reranker-0.6b','平衡選擇／約一秒多','兩個小模型組合的實測 Top-1 為 89.33%；若容量更緊，Gemma 2 + Qwen 0.6B 為 89.00%、0.884 GiB。')
choose+=recommendation('qwen-0.6b','qwen-reranker-4b','品質優先／容許數秒等待','達到本輪最高 Top-1，適合先評估批次搜尋或品質優先流程；Gemma 2 組合也同分，權重合計更小。')
choose+='''</div><div class="hardware"><h3>把組合放到你的硬體上</h3><div class="three"><div><h4>8 GB 等入門裝置</h4><p>先評估 Granite、Gemma 2、BGE-M3 等單模型。能否加入重排器，還取決於系統可用記憶體、文件長度與服務配置。</p></div><div><h4>16 GB 等中階裝置</h4><p>先試小型 embedder + 0.6B／BGE 重排器。若要試 4B 重排器，須另外檢查執行時尖峰用量與延遲。</p></div><div><h4>32 GB 以上／工作站</h4><p>可評估 4B 重排器；若只要向量搜尋，本輪 8B 的品質最佳。更多記憶體不保證較高命中率。</p></div></div><p class="small">以上是選型起點，未在這些硬體上實測。CPU、獨立顯示卡 VRAM、Apple 統一記憶體不能直接互換；不要把 M3 Ultra 的毫秒數當成筆電預期速度。</p></div><div class="chooser"><div><h3>用模型容量預算，縮小選擇</h3><p>只比較本輪已測組合；同分時先選較快的組合。沒有替其他硬體預測速度。</p></div><label>權重容量預算<select id="budget"><option value="0.15">0.15 GiB</option><option value="0.35">0.35 GiB</option><option value="0.65">0.65 GiB</option><option value="1">1 GiB</option><option value="1.25" selected>1.25 GiB</option><option value="4.6">4.6 GiB</option><option value="8">8 GiB</option><option value="12">12 GiB</option></select></label><label>使用方式<select id="mode"><option value="all">可使用重排器</option><option value="standalone">只用 embedder</option></select></label><div id="budget-result" aria-live="polite"></div><noscript><p>互動篩選需啟用 JavaScript；全部組合仍可直接閱讀下方表格。</p></noscript></div></section>'''
results='<section id="results">'+sectionhead('03 / 所有重要結果','準確度、方向差異與等待時間，一起看。','Top-1：相關文章排第一名的比例。三方向平均權重相同；p95 表示 95% 測量不超過此時間。')+'<div class="results-panels"><article class="panel interactive-chart"><h3 id="chart-title">不加重排器，誰先找到對的資料？</h3><p>切換方向與重排器，比較同一款 embedder 的命中率如何改變。</p>'+bars()+'</article><article class="panel"><h3>加上不同 reranker 的整體差異</h3><p>下表各跨五款 embedder，使用相同的 300 個任務，共 1,500 次測量。</p>'+table(['重排器','平均 Top-1','重排平均','重排 p95'],[[link(p['reranker']),pct(p['top1']),ms(p['rerank_ms_mean']),ms(p['rerank_ms_p95'])] for p in A['rerankers']])+'<p class="note">重排器只能調整前 50 篇的順序；若正確文章沒進候選，就無法把它找回來。</p></article></div><h3 class="table-title">22 種組合完整比較</h3><p>點選欄位標題即可排序，再點一次反向。命中率預設由高到低，時間與容量預設由低到高；可與文字篩選一起使用。每列 300 次測量，方向各 100 題。</p><label class="filter">快速篩選組合 <input id="table-filter" type="search" placeholder="例如 Qwen、BGE、Gemma" aria-controls="comparison"></label><div id="comparison">'+comparison_table()+'</div><p id="sort-status" class="small" aria-live="polite">排序：平均 Top-1，由高到低</p><p id="filter-count" aria-live="polite"></p><p class="small">總時間＝query embedding＋exact cosine 搜尋＋重排；不含模型載入、建索引、佇列或對外服務網路。<a href="data/all-66-groups.csv" download>下載 66 組詳細 CSV</a> · <a href="methods.html#metrics">了解 MRR、nDCG 與 Recall</a></p></section>'
method='''<section class="method-strip"><div><p class="eyebrow">04 / 測試方式，先讀這幾句就夠</p><h2>同一批問題，<br>換模型比較。</h2></div><div><p>從 MLQA validation 固定抽出三方向各 100 題，保留各方向完整文章庫：430、443、978 篇。先用 embedder 找前 50 篇，再比較要不要加 reranker。</p><p>只有正式採用的 guarded v3 紀錄納入結果。每方向 100 題，一題就是 1 個百分點；小差異可能隨題目改變。本輪沒有測英文查中文、大型知識庫與併發服務。</p><div class="hero-actions"><a class="button" href="methods.html">完整測試說明</a><a class="button secondary" href="resources.html">取得程式與全部資料</a></div></div></section>'''
page('index.html','找到對的資料，選對模型組合',hero+findings+choose+results+method,'中英 embedder 與 reranker 本機實測：7 款 embedding、3 款重排器，22 組配對的品質、速度與模型容量比較。')

# Independent, crawlable model pages with source citations.
for k,m in M.items():
 isembed=k in E; w=A['models'][k]; related=[p for p in A['pairs'] if p['embedding']==k] if isembed else [p for p in A['pairs'] if p['reranker']==k]
 baseline=pair(k) if isembed else next(x for x in A['rerankers'] if x['reranker']==k)
 body=intro('MODEL / '+('EMBEDDER' if isembed else 'RERANKER'),esc(m['name']),esc(m['description_zh']))
 body+=f'<div class="model-stats"><div><strong>{pct(baseline["top1"])}</strong><span>{"單用模型" if isembed else "跨五款 embedder"}平均 Top-1</span></div><div><strong>{ms(baseline["total_ms_mean"] if isembed else baseline["rerank_ms_mean"])}</strong><span>{"query＋搜尋" if isembed else "重排50篇"}平均時間</span></div><div><strong>{w["weight_gib"]:.3f} GiB</strong><span>本次 Q8_0 權重</span></div></div>'
 body+='<section class="two"><article class="panel"><h2>什麼情況值得考慮？</h2><p>'+esc(m['strength_zh'])+'</p><p class="note">'+esc(m['caveat_zh'])+'</p></article><article class="panel"><h2>模型與本次設定</h2>'+table(['項目','內容'],[['角色','向量檢索' if isembed else '候選文章重排'],['參數規模',esc(m['params'])],['維度',str(m['dimensions'] or '不適用')],['Pooling',esc(m['pooling'])],['模型授權',esc(m['license'])],['來源',f'<a href="{m["official_url"]}">官方模型卡 ↗</a>']])+'</article></section>'
 rows=[]
 for c in DIRS:
  g=group(k,'standalone',c) if isembed else next(x for x in A['rerankers'] if x['reranker']==k)['directions'][c]
  rows.append([DIRS[c],pct(g['top1']),f'{g["mrr10"]:.4f}',f'{g["ndcg10"]:.4f}',pct(g['recall10']),pct(g['recall50']),ms(g['total_ms_mean'] if isembed else g['rerank_ms_mean'])])
 body+='<section>'+sectionhead('RESULTS','三個方向分開看','單模型各方向 100 次；reranker 各方向跨五款 embedder 共 500 次，仍重複使用同一批 100 題。')+table(['方向','Top-1','MRR@10','nDCG@10','Recall@10','Recall@50','平均時間'],rows)+'<p class="small">所有時間只代表本次 M3 Ultra；指標定義見<a href="../methods.html#metrics">完整說明</a>。</p></section>'
 body+='<section><h2>已測組合</h2>'+table(['Embedder','Reranker','平均 Top-1','MRR@10','nDCG@10','平均總時間','總時間 p95','權重 GiB'],[[link(p['embedding'],'../'),link(p['reranker'],'../') if p['reranker']!='standalone' else '不重排',pct(p['top1']),f'{p["mrr10"]:.4f}',f'{p["ndcg10"]:.4f}',ms(p['total_ms_mean']),ms(p['total_ms_p95']),f'{p["weight_gib_sum"]:.3f}'] for p in related])+('</section>' if k not in ['granite-97m-r2','f2llm-v2-0.6b'] else '<p class="note">本輪只測 standalone，沒有搭配 reranker 的結果；不能宣稱尚未測試的配對最有效。</p></section>')
